d" class="w-full p-2 border rounded"><option value="cash">cash</option><option value="card">card</option><option value="e-wallet">E-wallet (GCash)</option></select><input x-show="paymentMethod==='cash'" name="amount_received" type="number" step=".01" placeholder="Cash received" class="w-full p-2 border rounded"><input x-show="paymentMethod==='e-wallet'" name="proof_of_payment" type="file" accept=".jpg,.jpeg,.png" class="w-full p-2 border rounded"><div class="flex justify-between font-bold"><span>Total</span><span x-text="money(subtotal())"></span></div><button :disabled="!items.length || {{ $shift ? 'false' : 'true' }}" class="w-full bg-cyan-500 text-white p-3 rounded">Charge order</button></form></div></div><script>function posCart(){return{items:[],paymentMethod:'cash',add(i){let f=this.items.find(x=>x.id===i.id);f?f.quantity++:this.items.push({...i,quantity:1})},remove(i){this.items.splice(i,1)},subtotal(){return this.items.reduce((s,i)=>s+i.price*i.quantity,0)},money(v){return '₱'+Number(v).toFixed(2)}}}</script>
